# MyFitnessPal Integration
import requests
from datetime import datetime

MFP_API_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9"
BASE_URL = "https://api.myfitnesspal.com/v1"

def get_daily_nutrition(date=None):
    """Get nutrition data for a specific date"""
    if not date:
        date = datetime.now().strftime("%Y-%m-%d")

    response = requests.get(
        f"{BASE_URL}/diary",
        headers={"Authorization": f"Bearer {MFP_API_KEY}"},
        params={"date": date}
    )
    return response.json()

def track_meal(food_name, quantity, unit, meal_type):
    """Log a meal in MyFitnessPal"""
    response = requests.post(
        f"{BASE_URL}/entries",
        headers={"Authorization": f"Bearer {MFP_API_KEY}"},
        json={
            "food_name": food_name,
            "quantity": quantity,
            "unit": unit,
            "meal_type": meal_type
        }
    )
    return response.json()
